import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as s,af as r}from"./chunks/mermaid.YsAH9es0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Cursor and GitHub Copilot Official Practices","description":"What the official Cursor and GitHub Copilot docs say about context rules, subagents and custom agents, hooks, network defaults and code review, with two team-level takeaways.","frontmatter":{"title":"Cursor and GitHub Copilot Official Practices","description":"What the official Cursor and GitHub Copilot docs say about context rules, subagents and custom agents, hooks, network defaults and code review, with two team-level takeaways.","domain":"product","tags":["coding-agent"],"role":"reference"},"headers":[],"relativePath":"products/cursor/cursor-copilot-official-practices.md","filePath":"products/cursor/cursor-copilot-official-practices.md","lastUpdated":1793277967000}'),a={name:"products/cursor/cursor-copilot-official-practices.md"};function i(n,t,c,l,d,u){return s(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="cursor-and-github-copilot-official-practices" tabindex="-1">Cursor and GitHub Copilot Official Practices <a class="header-anchor" href="#cursor-and-github-copilot-official-practices" aria-label="Permalink to &quot;Cursor and GitHub Copilot Official Practices&quot;">​</a></h1><p><strong>Bottom line</strong>: Both products use files you can commit to the repository as the main way to carry team conventions, but they cover different surfaces and have different network defaults. Treat each default as a starting point to verify in your own setup, not as a guarantee.</p><blockquote><p><strong>Audience</strong>: engineers and tech leads comparing or adopting Cursor and GitHub Copilot in a team. <strong>Prerequisites</strong>: basic use of either product. See <a href="./cursor.html">Cursor</a> and the <a href="./cursor-cheatsheet.html">Cursor Cheatsheet</a>. <strong>Non-goal</strong>: this is not a feature reference. It covers only claims backed by quoted official text.</p></blockquote><p>Sources were fetched on 2026-10-21; the page list is at the end. Where the fetched text did not support a value, this page says so instead of guessing. The Copilot pages cover different surfaces (VS Code, cloud agent, CLI), so each row names its scope.</p><h2 id="cursor" tabindex="-1">Cursor <a class="header-anchor" href="#cursor" aria-label="Permalink to &quot;Cursor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>What the docs say</th></tr></thead><tbody><tr><td>Context rules</td><td>Project rules must use the <code>.mdc</code> extension. &quot;Keep rules under 500 lines&quot; is listed as a best practice, so it is a recommendation, not a validated limit. The fetched text does not establish the rules directory.</td></tr><tr><td>Subagents</td><td>Each subagent runs in its own context window, handles one type of work and returns the result to the parent. It starts with a clean context.</td></tr><tr><td>Hooks</td><td>Hooks use custom scripts to observe, control and extend the agent loop. They are spawned processes that talk JSON over stdio. The fetched text does not list all events.</td></tr><tr><td>Network sandbox</td><td>In the sandbox network policy, deny always wins over allow. In the documented &quot;allow only listed domains&quot; example, traffic is denied by default. That default belongs to the example, not to every project.</td></tr><tr><td>Code review</td><td>Bugbot reviews pull requests for bugs, security issues and code quality, and comments with explanations and fix suggestions.</td></tr></tbody></table><h2 id="github-copilot" tabindex="-1">GitHub Copilot <a class="header-anchor" href="#github-copilot" aria-label="Permalink to &quot;GitHub Copilot&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Scope</th><th>What the docs say</th></tr></thead><tbody><tr><td>Context rules</td><td>Repository instructions (VS Code page)</td><td>Repository-wide instructions apply to all requests made in the context of that repository. With <code>AGENTS.md</code>, the nearest file in the directory tree takes precedence.</td></tr><tr><td>Custom agents</td><td>Cloud agent</td><td>An agent profile is a Markdown file with YAML frontmatter declaring name, description, tools and MCP servers. The prompt of one profile is limited to 30,000 characters; this is a per-profile limit, not a budget for repository context files.</td></tr><tr><td>Hooks</td><td>CLI and cloud agent</td><td>Hooks run custom shell commands at key points of an agent workflow, such as session start or end, prompt submission and tool calls. The page states its examples target the CLI and the cloud agent.</td></tr><tr><td>Network</td><td>Cloud agent</td><td>Internet access is restricted by a firewall by default, and the firewall applies only to processes the agent starts through its Bash tool. The fetched pages do not describe local sandboxing.</td></tr><tr><td>Code review</td><td>Code review</td><td>Feedback includes suggested changes that can be applied in a few clicks where possible. Review comments behave like human review comments.</td></tr></tbody></table><h2 id="side-by-side" tabindex="-1">Side by side <a class="header-anchor" href="#side-by-side" aria-label="Permalink to &quot;Side by side&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Cursor</th><th>GitHub Copilot</th></tr></thead><tbody><tr><td>Context rules</td><td><code>.mdc</code> project rules; under 500 lines recommended</td><td>Repository instructions; nearest <code>AGENTS.md</code> wins</td></tr><tr><td>Subagents / custom agents</td><td>Isolated context window, clean start</td><td>Markdown profile with YAML frontmatter; 30,000-character prompt cap</td></tr><tr><td>Hooks</td><td>Scripts over stdio JSON</td><td>Shell commands at lifecycle points (CLI, cloud agent)</td></tr><tr><td>Network posture</td><td>Deny beats allow; example config denies by default</td><td>Firewall limits internet access by default (Bash-launched processes only)</td></tr><tr><td>Review</td><td>Bugbot comments with fix suggestions</td><td>Applicable suggestions; comments like human comments</td></tr></tbody></table><h2 id="two-practices-to-adopt" tabindex="-1">Two practices to adopt <a class="header-anchor" href="#two-practices-to-adopt" aria-label="Permalink to &quot;Two practices to adopt&quot;">​</a></h2><ol><li><strong>Split team conventions into small topic files.</strong> Cursor recommends keeping a rule under 500 lines, and Copilot gives the nearest <code>AGENTS.md</code> precedence in a directory tree. Put shared conventions at the root and package-specific ones next to the code. Basis: the Cursor line recommendation and the Copilot nearest-file rule above.</li><li><strong>Start network access from deny, then allow per dependency.</strong> Cursor&#39;s sandbox policy has deny over allow, and Copilot&#39;s cloud agent restricts internet access by default. Keep those defaults and open only the domains your build needs. Basis: the network rows above; the Cursor default applies to the documented example configuration only.</li></ol><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li>Reading the 500-line figure as an enforced limit. It is a recommendation.</li><li>Reading the 30,000-character figure as a limit on repository instructions. It applies to one agent profile.</li><li>Assuming the Copilot firewall covers every process. It covers processes the agent starts through Bash.</li><li>Assuming a Copilot setting applies on every surface. Check the scope column.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Compare these defaults with your team&#39;s actual configuration in the <a href="./cursor-cheatsheet.html">Cursor Cheatsheet</a>.</li><li>For the Claude Code counterpart, see <a href="./../claude/claude-code-official-practices.html">Claude Code Official Practices</a>.</li></ul><h2 id="not-established" tabindex="-1">Not established <a class="header-anchor" href="#not-established" aria-label="Permalink to &quot;Not established&quot;">​</a></h2><ul><li>Cursor: the permission and allowlist page, and the rules directory.</li><li>Copilot: local sandboxing, and a hook failure-blocking switch.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>Fetched 2026-10-21:</p><ul><li><a href="https://cursor.com/docs/rules" target="_blank" rel="noreferrer">https://cursor.com/docs/rules</a></li><li><a href="https://cursor.com/docs/subagents" target="_blank" rel="noreferrer">https://cursor.com/docs/subagents</a></li><li><a href="https://cursor.com/docs/hooks" target="_blank" rel="noreferrer">https://cursor.com/docs/hooks</a></li><li><a href="https://cursor.com/docs/reference/sandbox" target="_blank" rel="noreferrer">https://cursor.com/docs/reference/sandbox</a></li><li><a href="https://cursor.com/docs/bugbot" target="_blank" rel="noreferrer">https://cursor.com/docs/bugbot</a></li><li><a href="https://docs.github.com/en/copilot/how-tos/copilot-in-your-ide/customize-copilot/configure-custom-instructions/add-repository-instructions-in-your-ide" target="_blank" rel="noreferrer">https://docs.github.com/en/copilot/how-tos/copilot-in-your-ide/customize-copilot/configure-custom-instructions/add-repository-instructions-in-your-ide</a></li><li><a href="https://docs.github.com/en/copilot/how-tos/copilot-on-github/customize-copilot/customize-cloud-agent/create-custom-agents" target="_blank" rel="noreferrer">https://docs.github.com/en/copilot/how-tos/copilot-on-github/customize-copilot/customize-cloud-agent/create-custom-agents</a></li><li><a href="https://docs.github.com/en/copilot/concepts/customizations/hooks" target="_blank" rel="noreferrer">https://docs.github.com/en/copilot/concepts/customizations/hooks</a></li><li><a href="https://docs.github.com/en/copilot/how-tos/copilot-on-github/customize-copilot/customize-the-firewall" target="_blank" rel="noreferrer">https://docs.github.com/en/copilot/how-tos/copilot-on-github/customize-copilot/customize-the-firewall</a></li><li><a href="https://docs.github.com/en/copilot/how-tos/use-copilot-agents/use-code-review" target="_blank" rel="noreferrer">https://docs.github.com/en/copilot/how-tos/use-copilot-agents/use-code-review</a></li></ul>',21)])])}const g=e(a,[["render",i]]);export{b as __pageData,g as default};
